Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
mptcp: sendmsg: reset iter on error redux

This fix wasn't correct: When this function is invoked from the
retransmission worker, the iterator contains garbage and resetting
it causes a crash.

As the work queue should not be performance critical also zero the
msghdr struct.

Fixes: 35759383133f64d "(mptcp: sendmsg: reset iter on error)"
Signed-off-by: Florian Westphal <fw@strlen.de>
Signed-off-by: David S. Miller <davem@davemloft.net>

Here is the root cause:
The bug was caused by the iterator in the `mptcp_sendmsg_frag` function containing garbage values when the function was invoked from the retransmission worker. Resetting this iterator without checking its state led to a crash. Additionally, the `msghdr` structure was not properly initialized, which could result in undefined behavior when accessed.

Here is the patch:

 static int mptcp_sendmsg_frag(struct sock *sk, struct sock *ssk,
 			      struct msghdr *msg, struct mptcp_data_frag *dfrag,
 			      long *timeo, int *pmss_now,
 			      int *ps_goal)
 {
 	int mss_now, avail_size, size_goal, offset, ret, frag_truesize = 0;
 	bool dfrag_collapsed, can_collapse = false;
 	struct mptcp_sock *msk = mptcp_sk(sk);
 	struct mptcp_ext *mpext = NULL;
 	bool retransmission = !!dfrag;
 	struct sk_buff *skb, *tail;
 	struct page_frag *pfrag;
 	struct page *page;
 	u64 *write_seq;
 	size_t psize;

 	/* use the mptcp page cache so that we can easily move the data
 	 * from one substream to another, but do per subflow memory accounting
 	 * Note: pfrag is used only !retransmission, but the compiler if
 	 * fooled into a warning if we don't init here
 	 */
 	pfrag = sk_page_frag(sk);
 	if (!retransmission) {
 		write_seq = &msk->write_seq;
 		page = pfrag->page;
 	} else {
 		write_seq = &dfrag->data_seq;
 		page = dfrag->page;
 	}

 	/* compute copy limit */
 	mss_now = tcp_send_mss(ssk, &size_goal, msg->msg_flags);
 	*pmss_now = mss_now;
 	*ps_goal = size_goal;
 	avail_size = size_goal;
 	skb = tcp_write_queue_tail(ssk);
 	if (skb) {
 		mpext = skb_ext_find(skb, SKB_EXT_MPTCP);

 		/* Limit the write to the size available in the
 		 * current skb, if any, so that we create at most a new skb.
 		 * Explicitly tells TCP internals to avoid collapsing on later
 		 * queue management operation, to avoid breaking the ext <->
 		 * SSN association set here
 		 */
 		can_collapse = (size_goal - skb->len > 0) &&
 			      mptcp_skb_can_collapse_to(*write_seq, skb, mpext);
 		if (!can_collapse)
 			TCP_SKB_CB(skb)->eor = 1;
 		else
 			avail_size = size_goal - skb->len;
 	}

 	if (!retransmission) {
 		/* reuse tail pfrag, if possible, or carve a new one from the
 		 * page allocator
 		 */
 		dfrag = mptcp_rtx_tail(sk);
 		offset = pfrag->offset;
 		dfrag_collapsed = mptcp_frag_can_collapse_to(msk, pfrag, dfrag);
 		if (!dfrag_collapsed) {
 			dfrag = mptcp_carve_data_frag(msk, pfrag, offset);
 			offset = dfrag->offset;
 			frag_truesize = dfrag->overhead;
 		}
 		psize = min_t(size_t, pfrag->size - offset, avail_size);

 		/* Copy to page */
 		pr_debug("left=%zu", msg_data_left(msg));
 		psize = copy_page_from_iter(pfrag->page, offset,
 					    min_t(size_t, msg_data_left(msg),
 						  psize),
 					    &msg->msg_iter);
 		pr_debug("left=%zu", msg_data_left(msg));
 		if (!psize)
 			return -EINVAL;

 		if (!sk_wmem_schedule(sk, psize + dfrag->overhead)) {
 			iov_iter_revert(&msg->msg_iter, psize);
 			return -ENOMEM;
 		}
 	} else {
 		offset = dfrag->offset;
 		psize = min_t(size_t, dfrag->data_len, avail_size);
 	}

 	/* tell the TCP stack to delay the push so that we can safely
 	 * access the skb after the sendpages call
 	 */
 	ret = do_tcp_sendpages(ssk, page, offset, psize,
 			       msg->msg_flags | MSG_SENDPAGE_NOTLAST | MSG_DONTWAIT);
 	if (ret <= 0) {
-		iov_iter_revert(&msg->msg_iter, psize);
+		if (!retransmission)
+			iov_iter_revert(&msg->msg_iter, psize);
 		return ret;
 	}

 	frag_truesize += ret;
 	if (!retransmission) {
 		if (unlikely(ret < psize))
 			iov_iter_revert(&msg->msg_iter, psize - ret);

 		/* send successful, keep track of sent data for mptcp-level
 		 * retransmission
 		 */
 		dfrag->data_len += ret;
 		if (!dfrag_collapsed) {
 			get_page(dfrag->page);
 			list_add_tail(&dfrag->list, &msk->rtx_queue);
 			sk_wmem_queued_add(sk, frag_truesize);
 		} else {
 			sk_wmem_queued_add(sk, ret);
 		}

 		/* charge data on mptcp rtx queue to the master socket
 		 * Note: we charge such data both to sk and ssk
 		 */
 		sk->sk_forward_alloc -= frag_truesize;
 	}

 	/* if the tail skb extension is still the cached one, collapsing
 	 * really happened. Note: we can't check for 'same skb' as the sk_buff
 	 * hdr on tail can be transmitted, freed and re-allocated by the
 	 * do_tcp_sendpages() call
 	 */
 	tail = tcp_write_queue_tail(ssk);
 	if (mpext && tail && mpext == skb_ext_find(tail, SKB_EXT_MPTCP)) {
 		WARN_ON_ONCE(!can_collapse);
 		mpext->data_len += ret;
 		goto out;
 	}

 	skb = tcp_write_queue_tail(ssk);
 	mpext = __skb_ext_set(skb, SKB_EXT_MPTCP, msk->cached_ext);
 	msk->cached_ext = NULL;

 	memset(mpext, 0, sizeof(*mpext));
 	mpext->data_seq = *write_seq;
 	mpext->subflow_seq = mptcp_subflow_ctx(ssk)->rel_write_seq;
 	mpext->data_len = ret;
 	mpext->use_map = 1;
 	mpext->dsn64 = 1;

 	pr_debug("data_seq=%llu subflow_seq=%u data_len=%u dsn64=%d",
 		 mpext->data_seq, mpext->subflow_seq, mpext->data_len,
 		 mpext->dsn64);

 out:
 	if (!retransmission)
 		pfrag->offset += frag_truesize;
 	WRITE_ONCE(*write_seq, *write_seq + ret);
 	mptcp_subflow_ctx(ssk)->rel_write_seq += ret;

 	return ret;
 }


 static void mptcp_worker(struct work_struct *work)
 {
 	struct mptcp_sock *msk = container_of(work, struct mptcp_sock, work);
 	struct sock *ssk, *sk = &msk->sk.icsk_inet.sk;
 	int orig_len, orig_offset, mss_now = 0, size_goal = 0;
 	struct mptcp_data_frag *dfrag;
 	u64 orig_write_seq;
 	size_t copied = 0;
-	struct msghdr msg;
+	struct msghdr msg = {
+		.msg_flags = MSG_DONTWAIT,
+	};
 	long timeo = 0;

 	lock_sock(sk);
 	mptcp_clean_una(sk);
 	mptcp_check_data_fin_ack(sk);
 	__mptcp_flush_join_list(msk);
 	__mptcp_move_skbs(msk);

 	if (msk->pm.status)
 		pm_work(msk);

 	if (test_and_clear_bit(MPTCP_WORK_EOF, &msk->flags))
 		mptcp_check_for_eof(msk);

 	mptcp_check_data_fin(sk);

 	if (!test_and_clear_bit(MPTCP_WORK_RTX, &msk->flags))
 		goto unlock;

 	dfrag = mptcp_rtx_head(sk);
 	if (!dfrag)
 		goto unlock;

 	if (!mptcp_ext_cache_refill(msk))
 		goto reset_unlock;

 	ssk = mptcp_subflow_get_retrans(msk);
 	if (!ssk)
 		goto reset_unlock;

 	lock_sock(ssk);

-	msg.msg_flags = MSG_DONTWAIT;
 	orig_len = dfrag->data_len;
 	orig_offset = dfrag->offset;
 	orig_write_seq = dfrag->data_seq;
 	while (dfrag->data_len > 0) {
 		int ret = mptcp_sendmsg_frag(sk, ssk, &msg, dfrag, &timeo,
 					     &mss_now, &size_goal);
 		if (ret < 0)
 			break;

 		MPTCP_INC_STATS(sock_net(sk), MPTCP_MIB_RETRANSSEGS);
 		copied += ret;
 		dfrag->data_len -= ret;
 		dfrag->offset += ret;

 		if (!mptcp_ext_cache_refill(msk))
 			break;
 	}
 	if (copied)
 		tcp_push(ssk, msg.msg_flags, mss_now, tcp_sk(ssk)->nonagle,
 			 size_goal);

 	dfrag->data_seq = orig_write_seq;
 	dfrag->offset = orig_offset;
 	dfrag->data_len = orig_len;

 	mptcp_set_timeout(sk, ssk);
 	release_sock(ssk);

 reset_unlock:
 	if (!mptcp_timer_pending(sk))
 		mptcp_reset_timer(sk);

 unlock:
 	release_sock(sk);
 	sock_put(sk);
 }



